  /* An analogue clock as an SVG string. Colours follow the page theme unless
     `light` is set (white face on a dark card, used in the weather bubbles). */
  function clockSVG(h, m, o) {
    o = o || {};
    var size = o.size || 96;
    var face = o.light ? 'rgba(255,255,255,.14)' : 'var(--surface-2)';
    var ink = o.light ? '#fff' : 'var(--text-primary)';
    var soft = o.light ? 'rgba(255,255,255,.75)' : 'var(--text-secondary)';
    var hand = o.light ? '#ffd166' : 'var(--text-accent)';
    var alt = o.alt != null ? o.alt : digital(h, m, true);
    var s = '<svg class="tk-clock" viewBox="0 0 100 100" width="' + size + '" height="' + size + '" role="img" aria-label="' + alt + '">';
    s += '<circle cx="50" cy="50" r="46" fill="' + face + '" stroke="' + ink + '" stroke-width="' + (o.light ? 3 : 3.2) + '"/>';
    for (var i = 0; i < 60; i++) {
      var a = i * 6 * Math.PI / 180, big = i % 5 === 0;
      var r1 = big ? 37.5 : 40.5, r2 = 43;
      s += '<line x1="' + (50 + r1 * Math.sin(a)).toFixed(2) + '" y1="' + (50 - r1 * Math.cos(a)).toFixed(2) +
        '" x2="' + (50 + r2 * Math.sin(a)).toFixed(2) + '" y2="' + (50 - r2 * Math.cos(a)).toFixed(2) +
        '" stroke="' + (big ? ink : soft) + '" stroke-width="' + (big ? 2 : .8) + '" stroke-linecap="round"/>';
    }
    if (o.numbers !== false && size >= 56) {
      for (var n = 1; n <= 12; n++) {
        var b = n * 30 * Math.PI / 180;
        s += '<text x="' + (50 + 29.5 * Math.sin(b)).toFixed(2) + '" y="' + (50 - 29.5 * Math.cos(b) + 3.6).toFixed(2) +
          '" font-size="10" font-weight="600" text-anchor="middle" fill="' + soft + '" font-family="-apple-system,Segoe UI,Helvetica,Arial,sans-serif">' + n + '</text>';
      }
    }
    var ha = ((h % 12) + m / 60) * 30 * Math.PI / 180;
    var ma = m * 6 * Math.PI / 180;
    s += '<line x1="50" y1="50" x2="' + (50 + 22 * Math.sin(ha)).toFixed(2) + '" y2="' + (50 - 22 * Math.cos(ha)).toFixed(2) +
      '" stroke="' + ink + '" stroke-width="5.5" stroke-linecap="round"/>';
    s += '<line x1="50" y1="50" x2="' + (50 + 35 * Math.sin(ma)).toFixed(2) + '" y2="' + (50 - 35 * Math.cos(ma)).toFixed(2) +
      '" stroke="' + hand + '" stroke-width="3.2" stroke-linecap="round"/>';
    s += '<circle cx="50" cy="50" r="3.6" fill="' + hand + '" stroke="' + ink + '" stroke-width="1.2"/></svg>';
    return s;
  }

  /* The "past / to" diagram for the clarification page: the right half of the
     clock is PAST the hour, the left half is TO the next hour. */
  function pastToSVG(o) {
    o = o || {};
    var size = o.size || 260;
    var F = '-apple-system,Segoe UI,Helvetica,Arial,sans-serif';
    var s = '<svg class="tk-pastto" viewBox="-62 -30 224 166" width="' + size + '" role="img" aria-label="A clock. The right half says past. The left half says to.">';
    s += '<path d="M50,50 L50,4 A46,46 0 0 1 50,96 Z" fill="var(--pos-time-bg)"/>';
    s += '<path d="M50,50 L50,96 A46,46 0 0 1 50,4 Z" fill="var(--bg-q)"/>';
    s += '<circle cx="50" cy="50" r="46" fill="none" stroke="var(--text-primary)" stroke-width="2.6"/>';
    s += '<line x1="50" y1="18" x2="50" y2="82" stroke="var(--text-primary)" stroke-width="1.2" stroke-dasharray="3,3"/>';
    for (var n = 1; n <= 12; n++) {
      var b = n * 30 * Math.PI / 180;
      s += '<text x="' + (50 + 38 * Math.sin(b)).toFixed(2) + '" y="' + (50 - 38 * Math.cos(b) + 3.2).toFixed(2) +
        '" font-size="8.5" font-weight="600" text-anchor="middle" fill="var(--text-secondary)" font-family="' + F + '">' + n + '</text>';
    }
    s += '<text x="66" y="54" font-size="12.5" font-weight="800" text-anchor="middle" fill="var(--pos-time)" font-family="' + F + '">past</text>';
    s += '<text x="34" y="54" font-size="12.5" font-weight="800" text-anchor="middle" fill="var(--text-q)" font-family="' + F + '">to</text>';
    // the four landmarks round the outside
    s += '<text x="50" y="-14" font-size="9.5" font-weight="700" text-anchor="middle" fill="var(--text-primary)" font-family="' + F + '">o’clock</text>';
    s += '<text x="50" y="-4" font-size="8" text-anchor="middle" fill="var(--text-secondary)" font-family="' + F + '">:00</text>';
    s += '<text x="50" y="112" font-size="9.5" font-weight="700" text-anchor="middle" fill="var(--text-primary)" font-family="' + F + '">half past</text>';
    s += '<text x="50" y="122" font-size="8" text-anchor="middle" fill="var(--text-secondary)" font-family="' + F + '">:30</text>';
    s += '<text x="102" y="49" font-size="9.5" font-weight="700" text-anchor="start" fill="var(--pos-time)" font-family="' + F + '">quarter</text>';
    s += '<text x="102" y="60" font-size="9.5" font-weight="700" text-anchor="start" fill="var(--pos-time)" font-family="' + F + '">past <tspan font-weight="400" fill="var(--text-secondary)">:15</tspan></text>';
    s += '<text x="-2" y="49" font-size="9.5" font-weight="700" text-anchor="end" fill="var(--text-q)" font-family="' + F + '">quarter</text>';
    s += '<text x="-2" y="60" font-size="9.5" font-weight="700" text-anchor="end" fill="var(--text-q)" font-family="' + F + '"><tspan font-weight="400" fill="var(--text-secondary)">:45</tspan> to</text>';
    s += '</svg>';
    return s;
  }

