    [35.7, 139.7, 3.2], [34.7, 135.5, 2.6], [35.2, 136.9, 1.8], [43.1, 141.4, 1.2], [25, 121.5, 2], [14.6, 121, 2.4],
    [13.8, 100.5, 2.4], [10.8, 106.7, 2], [21, 105.8, 1.8], [3.1, 101.7, 1.8], [1.35, 103.8, 1.6], [-6.2, 106.8, 2.8],
    [-7.3, 112.7, 1.6], [-33.9, 151.2, 2], [-37.8, 145, 2], [-27.5, 153, 1.4], [-31.9, 115.9, 1.4], [-34.9, 138.6, 1.2],
    [-36.8, 174.8, 1.4], [21.3, -157.9, 1], [61.2, -149.9, .8], [64.1, -21.9, .7], [60.2, 24.9, 1.2], [59.3, 18.1, 1.2],
    [59.9, 10.7, 1.1], [55.7, 12.6, 1.2], [53.3, -6.3, 1.3], [55.9, -3.2, 1.1], [43.3, -2.9, 1], [43.6, 1.4, 1],
    [45.8, 4.8, 1.3], [43.3, 5.4, 1.3], [51.2, 6.8, 2], [48.1, 11.6, 1.6], [53.6, 10, 1.6], [46.2, 6.1, 1.2],
    [56.8, 60.6, 1.4], [55, 82.9, 1.4], [43.2, 76.9, 1.4], [41.3, 69.3, 1.6], [40.4, 49.9, 1.4], [41.7, 44.8, 1.1],
    [50.4, 30.5, 1.8], [53.9, 27.6, 1.4], [47, 28.9, 1], [42.7, 23.3, 1.3], [44.8, 20.5, 1.4], [45.8, 16, 1.1]
